window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-387ffb2f14f002b3"]={"versions": [{"id": "FIG-387ffb2f14f002b3", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Signalverlaufsdiagramm zur Sende- und Übertragungsmoduslogik (Transmission Mode) im AUTOSAR Classic Platform Kommunikationsstack (AUTOSAR COM, Modul <code>Com</code>). Das Diagramm illustriert das Mixed-Übertragungsverhalten (<code>ComTxModeMode = MIXED</code>) eines I-PDUs ohne Umschaltung des Transmission Mode Selectors (<code>TMS</code>), bei dem periodische Übertragungen mit ereignisgesteuerten Mehrfachübertragungen kombiniert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t):</strong> Horizontale Zeitbasis für Übertragungszeitpunkte und Timer-Intervalle.\n</li><li><strong>Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächliche Sendezeitpunkte bzw. Übertragungsanforderungen (<code>Com_SendSignal</code> / Sendeaufrufe an untere Schichten wie PduR) des I-PDUs.\n</li><li><strong>Sendeereignis (oranger Blitz mit V = x&#x27;):</strong> Signaländerung bzw. Ereignis, das eine spontane Übertragung anfordert.\n</li><li><strong>Periodischer Zyklus (t_c):</strong> Konfigurierter Zyklusabstand (<code>ComTxModeTimePeriod</code>) der zyklischen Übertragung.\n</li><li><strong>Wiederholungsabstand (t_d):</strong> Konfigurierte Zeitdauer (<code>ComTxModeRepetitionPeriod</code>) zwischen den n Wiederholungen im Ereignisfall.\n</li><li><strong>Mindestsendeabstand (dt bzw. $t_{r,\\min}$):</strong> Minimum Delay Timer (<code>ComMinimumDelayTime</code>), der den Mindestabstand aufeinanderfolgender Sendevorgänge absichert; dargestellt als dt bzw. Restlaufzeit $t_{r,\\min}$ zum Ereigniszeitpunkt sowie die verbleibende Wartezeit &gt;dt bis zur Wiederaufnahme der regulären Periodizität.\n</li><li><strong>Analysefenster (t):</strong> Übergeordnetes Zeitintervall unterhalb der Achse zur Betrachtung der Interaktion von MDT, Burst-Übertragungen und Periodizität.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre zyklische Phase:</strong> Das I-PDU wird zunächst im festen zyklischen Raster mit Periodendauer t_c übertragen.\n</li><li><strong>Ereigniseintritt und MDT-Verzögerung:</strong> Ein Sendeereignis (V = x&#x27;) tritt während eines laufenden Zyklus auf, während der Minimum Delay Timer (<code>ComMinimumDelayTime</code>, dt) noch aktiv ist (verbleibende Restzeit $t_{r,\\min}$).\n</li><li><strong>Verzögerter Burst-Start:</strong> Die erste ereignisgesteuerte Übertragung erfolgt unmittelbar nach Ablauf der Mindestverzögerungszeit $t_{r,\\min}$.\n</li><li><strong>Ereignisgesteuerte Wiederholungen:</strong> Es erfolgen insgesamt n = 3 Übertragungen im festen Abstand von t_d (<code>ComTxModeRepetitionPeriod</code>).\n</li><li><strong>Rückkehr zum zyklischen Muster:</strong> Nach Abschluss der n Übertragungen und Ablauf der Mindestabstandsbedingung (&gt;dt) wird das zyklische Senden mit dem Intervall t_c ab dem letzten Sendeimpuls bzw. entsprechend dem periodischen Schema fortgesetzt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfiguration:</strong> Relevant für die Parametrierung von <code>ComTxModeTrue</code> bzw. <code>ComTxModeFalse</code> mit <code>ComTxModeMode = MIXED</code>, <code>ComTxModeNumberOfRepetitions = 2</code> (entspricht n=3 Übertragungen gesamt: 1 Spontanübertragung + 2 Wiederholungen) und <code>ComTxModeRepetitionPeriod</code> (t_d).\n</li><li><strong>MDT-Interaktion:</strong> Zeigt normativ, dass ein spontanes Sendeereignis das <code>ComMinimumDelayTime</code> (dt) nicht verletzen darf; die spontane Aussendung wird bis zum Ablauf von $t_{r,\\min}$ verzögert.\n</li><li><strong>Wiederholungsabstand:</strong> <code>ComTxModeRepetitionPeriod</code> (t_d) muss größer oder gleich <code>ComMinimumDelayTime</code> gewählt werden, damit die Wiederholungen im projektierten Abstand abgesetzt werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-484c1e4d43cf4d7d", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Signalverlaufsdiagramm zur Sende- und Übertragungsmoduslogik (Transmission Mode) im AUTOSAR Classic Platform Kommunikationsstack (AUTOSAR COM, Modul <code>Com</code>). Das Diagramm illustriert das Mixed-Übertragungsverhalten (<code>ComTxModeMode = MIXED</code>) eines I-PDUs ohne Umschaltung des Transmission Mode Selectors (<code>TMS</code>), bei dem periodische Übertragungen mit ereignisgesteuerten Mehrfachübertragungen kombiniert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t):</strong> Horizontale Zeitbasis für Übertragungszeitpunkte und Timer-Intervalle.\n</li><li><strong>Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächliche Sendezeitpunkte bzw. Übertragungsanforderungen (<code>Com_SendSignal</code> / Sendeaufrufe an untere Schichten wie PduR) des I-PDUs.\n</li><li><strong>Sendeereignis (oranger Blitz mit V = x&#x27;):</strong> Signaländerung bzw. Ereignis, das eine spontane Übertragung anfordert.\n</li><li><strong>Periodischer Zyklus (t_c):</strong> Konfigurierter Zyklusabstand (<code>ComTxModeTimePeriod</code>) der zyklischen Übertragung.\n</li><li><strong>Wiederholungsabstand (t_d):</strong> Konfigurierte Zeitdauer (<code>ComTxModeRepetitionPeriod</code>) zwischen den n Wiederholungen im Ereignisfall.\n</li><li><strong>Mindestsendeabstand (dt bzw. $t_{r,\\min}$):</strong> Minimum Delay Timer (<code>ComMinimumDelayTime</code>), der den Mindestabstand aufeinanderfolgender Sendevorgänge absichert; dargestellt als dt bzw. Restlaufzeit $t_{r,\\min}$ zum Ereigniszeitpunkt sowie die verbleibende Wartezeit &gt;dt bis zur Wiederaufnahme der regulären Periodizität.\n</li><li><strong>Analysefenster (t):</strong> Übergeordnetes Zeitintervall unterhalb der Achse zur Betrachtung der Interaktion von MDT, Burst-Übertragungen und Periodizität.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre zyklische Phase:</strong> Das I-PDU wird zunächst im festen zyklischen Raster mit Periodendauer t_c übertragen.\n</li><li><strong>Ereigniseintritt und MDT-Verzögerung:</strong> Ein Sendeereignis (V = x&#x27;) tritt während eines laufenden Zyklus auf, während der Minimum Delay Timer (<code>ComMinimumDelayTime</code>, dt) noch aktiv ist (verbleibende Restzeit $t_{r,\\min}$).\n</li><li><strong>Verzögerter Burst-Start:</strong> Die erste ereignisgesteuerte Übertragung erfolgt unmittelbar nach Ablauf der Mindestverzögerungszeit $t_{r,\\min}$.\n</li><li><strong>Ereignisgesteuerte Wiederholungen:</strong> Es erfolgen insgesamt n = 3 Übertragungen im festen Abstand von t_d (<code>ComTxModeRepetitionPeriod</code>).\n</li><li><strong>Rückkehr zum zyklischen Muster:</strong> Nach Abschluss der n Übertragungen und Ablauf der Mindestabstandsbedingung (&gt;dt) wird das zyklische Senden mit dem Intervall t_c ab dem letzten Sendeimpuls bzw. entsprechend dem periodischen Schema fortgesetzt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfiguration:</strong> Relevant für die Parametrierung von <code>ComTxModeTrue</code> bzw. <code>ComTxModeFalse</code> mit <code>ComTxModeMode = MIXED</code>, <code>ComTxModeNumberOfRepetitions = 2</code> (entspricht n=3 Übertragungen gesamt: 1 Spontanübertragung + 2 Wiederholungen) und <code>ComTxModeRepetitionPeriod</code> (t_d).\n</li><li><strong>MDT-Interaktion:</strong> Zeigt normativ, dass ein spontanes Sendeereignis das <code>ComMinimumDelayTime</code> (dt) nicht verletzen darf; die spontane Aussendung wird bis zum Ablauf von $t_{r,\\min}$ verzögert.\n</li><li><strong>Wiederholungsabstand:</strong> <code>ComTxModeRepetitionPeriod</code> (t_d) muss größer oder gleich <code>ComMinimumDelayTime</code> gewählt werden, damit die Wiederholungen im projektierten Abstand abgesetzt werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5199311a596f6b14", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Signalverlaufsdiagramm zur Sende- und Übertragungsmoduslogik (Transmission Mode) im AUTOSAR Classic Platform Kommunikationsstack (AUTOSAR COM, Modul <code>Com</code>). Das Diagramm illustriert das Mixed-Übertragungsverhalten (<code>ComTxModeMode = MIXED</code>) eines I-PDUs ohne Umschaltung des Transmission Mode Selectors (<code>TMS</code>), bei dem periodische Übertragungen mit ereignisgesteuerten Mehrfachübertragungen kombiniert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (t):</strong> Horizontale Zeitbasis für Übertragungszeitpunkte und Timer-Intervalle.\n</li><li><strong>Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächliche Sendezeitpunkte bzw. Übertragungsanforderungen (<code>Com_SendSignal</code> / Sendeaufrufe an untere Schichten wie PduR) des I-PDUs.\n</li><li><strong>Sendeereignis (oranger Blitz mit V = x&#x27;):</strong> Signaländerung bzw. Ereignis, das eine spontane Übertragung anfordert.\n</li><li><strong>Periodischer Zyklus (t_c):</strong> Konfigurierter Zyklusabstand (<code>ComTxModeTimePeriod</code>) der zyklischen Übertragung.\n</li><li><strong>Wiederholungsabstand (t_d):</strong> Konfigurierte Zeitdauer (<code>ComTxModeRepetitionPeriod</code>) zwischen den n Wiederholungen im Ereignisfall.\n</li><li><strong>Mindestsendeabstand (dt bzw. $t_{r,\\min}$):</strong> Minimum Delay Timer (<code>ComMinimumDelayTime</code>), der den Mindestabstand aufeinanderfolgender Sendevorgänge absichert; dargestellt als dt bzw. Restlaufzeit $t_{r,\\min}$ zum Ereigniszeitpunkt sowie die verbleibende Wartezeit &gt;dt bis zur Wiederaufnahme der regulären Periodizität.\n</li><li><strong>Analysefenster (t):</strong> Übergeordnetes Zeitintervall unterhalb der Achse zur Betrachtung der Interaktion von MDT, Burst-Übertragungen und Periodizität.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Reguläre zyklische Phase:</strong> Das I-PDU wird zunächst im festen zyklischen Raster mit Periodendauer t_c übertragen.\n</li><li><strong>Ereigniseintritt und MDT-Verzögerung:</strong> Ein Sendeereignis (V = x&#x27;) tritt während eines laufenden Zyklus auf, während der Minimum Delay Timer (<code>ComMinimumDelayTime</code>, dt) noch aktiv ist (verbleibende Restzeit $t_{r,\\min}$).\n</li><li><strong>Verzögerter Burst-Start:</strong> Die erste ereignisgesteuerte Übertragung erfolgt unmittelbar nach Ablauf der Mindestverzögerungszeit $t_{r,\\min}$.\n</li><li><strong>Ereignisgesteuerte Wiederholungen:</strong> Es erfolgen insgesamt n = 3 Übertragungen im festen Abstand von t_d (<code>ComTxModeRepetitionPeriod</code>).\n</li><li><strong>Rückkehr zum zyklischen Muster:</strong> Nach Abschluss der n Übertragungen und Ablauf der Mindestabstandsbedingung (&gt;dt) wird das zyklische Senden mit dem Intervall t_c ab dem letzten Sendeimpuls bzw. entsprechend dem periodischen Schema fortgesetzt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfiguration:</strong> Relevant für die Parametrierung von <code>ComTxModeTrue</code> bzw. <code>ComTxModeFalse</code> mit <code>ComTxModeMode = MIXED</code>, <code>ComTxModeNumberOfRepetitions = 2</code> (entspricht n=3 Übertragungen gesamt: 1 Spontanübertragung + 2 Wiederholungen) und <code>ComTxModeRepetitionPeriod</code> (t_d).\n</li><li><strong>MDT-Interaktion:</strong> Zeigt normativ, dass ein spontanes Sendeereignis das <code>ComMinimumDelayTime</code> (dt) nicht verletzen darf; die spontane Aussendung wird bis zum Ablauf von $t_{r,\\min}$ verzögert.\n</li><li><strong>Wiederholungsabstand:</strong> <code>ComTxModeRepetitionPeriod</code> (t_d) muss größer oder gleich <code>ComMinimumDelayTime</code> gewählt werden, damit die Wiederholungen im projektierten Abstand abgesetzt werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-387ffb2f14f002b3", "to": "FIG-484c1e4d43cf4d7d", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-484c1e4d43cf4d7d", "to": "FIG-5199311a596f6b14", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
